#!/usr/bin/env node
/* Offline benchmarking against catalog generated by prepare_photo_bank.py.
Usage: node atelier/benchmarks/evaluate-outfits.mjs look-benchmark/garments.json look-benchmark/looks.json
The output contains suggestions, quality warnings and relative local photo paths.
No AI calls, network requests or personal profile access. */
import fs from "node:fs";
const [sourceFile,outputFile]=process.argv.slice(2);
if(!sourceFile||!outputFile){
 console.error("Usage: node atelier/benchmarks/evaluate-outfits.mjs catalog.json output.json");
 process.exit(2);
}
const catalog=JSON.parse(fs.readFileSync(sourceFile,"utf8"));
if(!Array.isArray(catalog))throw Error("Expected array of garment records");
const src=fs.readFileSync(new URL("../atelier.js",import.meta.url),"utf8");
const document={addEventListener(){},querySelector(){return null},querySelectorAll(){return []}};
const sessionStorage={removeItem(){},getItem(){return null}};
const evaluate=new Function("document","sessionStorage","crypto","input",src+`
appState.profile={id:"offline-benchmark"};
appState.data=emptyData();
const categories=["Arriba","Abajo","Vestidos","Capas","Zapatos","Bolsos","Accesorios"];
const groups=new Map(categories.map(c=>[c,[]]));
for(const item of input){const a=groups.get(item.category);if(a)a.push({...item,style:item.style||"casual",season:item.season||"all",color:item.color||"Negro"})}
const sizes=[20,100,500,1000],result=[],totals=[];
for(const size of sizes){
 const wardrobe=[],offset=new Map(categories.map(c=>[c,0]));
 while(wardrobe.length<Math.min(size,input.length)){
  let changed=false;
  for(const category of categories){
   const source=groups.get(category),i=offset.get(category);
   if(i<source.length&&wardrobe.length<Math.min(size,input.length)){wardrobe.push(source[i]);offset.set(category,i+1);changed=true}
  }
  if(!changed)break;
 }
 appState.data.garments=wardrobe;appState.data.looks=[];appState.data.wearLogs=[];
 for(const [temp,date] of [[8,"2026-01-15"],[17,"2026-04-15"],[28,"2026-07-15"]])
 for(const occasion of ["daily","work","event","party","beach","home"]){
  const looks=rankOutfits({max:8,temp,date,occasion});
  for(const [i,look] of looks.entries()){
   const gs=look.garments;
   const shoes=gs.filter(g=>g.category==="Zapatos");
   const hats=gs.filter(g=>/gorro|beanie|pasamonta|balaclava/i.test(g.name||""));
   const summer=shoes.some(g=>/chancl|flip.flop|sandali?as?/i.test(g.name||""));
   const flags=[];
   if(!lookComplete(gs))flags.push("incomplete_base");
   if(temp<19&&summer)flags.push("summer_shoes_in_cold");
   if(temp>=20&&hats.length)flags.push("winter_hat_in_heat");
   if(summer&&hats.length)flags.push("mixed_summer_winter");
   if(occasion==="home"&&shoes.length)flags.push("shoes_at_home");
   result.push({id:size+"-"+temp+"-"+occasion+"-"+i,size,temperature:temp,occasion,score:look.score,flags,
    garments:gs.map(g=>({id:g.id,name:g.name,category:g.category,image:g.image,color:g.color,style:g.style})),
    reasons:look.reasons,warnings:look.warnings});
  }
  totals.push({size,temperature:temp,occasion,generated:looks.length});
 }
}
return {looks:result,scenarios:totals};
`);
const report=evaluate(document,sessionStorage,{randomUUID:()=>"audit"},catalog);
fs.writeFileSync(outputFile,JSON.stringify(report,null,2));
console.log("Analyzed "+report.scenarios.length+" scenarios and generated "+report.looks.length+" looks");
console.log("Flagged looks: "+report.looks.filter(l=>l.flags.length).length+"; inspect all results visually.");
